t = int(input())
for m in range(t):
	(n, q) = map(int, input().split())
	arr = [int(x) for x in input().split()]
	grap = {}
	for i in range(n):
		grap[arr[i]] = i
	arr2 = sorted(arr)
	grap2 = {}
	for i in range(n):
		grap2[arr2[i]] = i
	for l in range(q):
		x = int(input())
		low = 0
		high = n - 1
		left = 0
		right = 0
		flag = 0
		swap = 0
		mini_ele = grap2[x]
		maxi_ele = n - 1 - grap2[x]
		while low <= high:
			mid = (low + high) // 2
			if arr[mid] == x:
				break
			elif grap[x] > mid:
				if arr[mid] < x:
					low = mid + 1
				else:
					if right == 0:
						swap += 1
						left += 1
					else:
						right -= 1
					low = mid + 1
				mini_ele -= 1
				if mini_ele < 0:
					flag = 1
					break
			else:
				if arr[mid] > x:
					high = mid - 1
				else:
					if left == 0:
						swap += 1
						right += 1
					else:
						left -= 1
					high = mid - 1
				maxi_ele -= 1
				if maxi_ele < 0:
					flag = 1
					break
		if flag == 1:
			print(-1)
		else:
			print(swap)
